[hidden] { display: none !important; }
:root { color-scheme: dark; --ink:#182329; --panel:#233239; --line:#3c5057; --paper:#f4f0dc; --muted:#a8b5ad; --lime:#c7f36b; --coral:#ff8b72; }
* { box-sizing:border-box; }
body { margin:0; min-height:100vh; display:grid; place-items:center; padding:24px 16px; background-color:var(--ink); background-image:radial-gradient(#304148 1px, transparent 1px); background-size:18px 18px; color:var(--paper); font:16px/1.5 system-ui,-apple-system,"Segoe UI",sans-serif; }
.panel { width:min(100%,540px); padding:clamp(22px,6vw,38px); border:2px solid #53666a; border-radius:12px; background:var(--panel); box-shadow:8px 8px 0 #10191d; }
.header { display:flex; align-items:center; gap:17px; margin-bottom:30px; }
.pixel-clock { width:52px; height:52px; display:grid; place-items:center; flex:none; border:4px solid var(--lime); box-shadow:inset 0 0 0 4px var(--panel), inset 0 0 0 7px var(--lime); }
.pixel-clock span { width:6px; height:6px; background:var(--lime); box-shadow:0 -12px var(--lime), 0 12px var(--lime), -12px 0 var(--lime), 12px 0 var(--lime); }
.eyebrow, footer { margin:0; color:var(--muted); font-size:12px; font-weight:800; letter-spacing:.14em; }
h1 { margin:0; font-size:clamp(26px,7vw,34px); line-height:1.15; letter-spacing:-.04em; }
.alarm-form { display:grid; grid-template-columns:1fr 1.2fr; gap:16px; padding:20px; border:1px solid var(--line); border-radius:8px; background:#1d2a30; }
label { display:grid; gap:7px; color:var(--muted); font-size:14px; font-weight:700; }
.time-fields { display:flex; align-items:end; gap:8px; }
.time-fields label { min-width:0; flex:1; }
input { width:100%; min-width:0; height:46px; padding:8px 11px; border:1px solid #53666a; border-radius:5px; outline:none; background:#111d22; color:var(--paper); font:inherit; }
input:focus { border-color:var(--lime); box-shadow:0 0 0 3px #c7f36b33; }
.separator { padding-bottom:8px; color:var(--lime); font-size:24px; font-weight:800; }
.optional { font-size:12px; font-weight:500; }
.add-button { grid-column:1/-1; min-height:48px; border:0; border-radius:5px; background:var(--lime); color:var(--ink); font:inherit; font-weight:850; cursor:pointer; transition:transform .12s,filter .12s,box-shadow .12s; }
.add-button span { font-size:22px; vertical-align:-1px; }
button { transition:transform .12s,filter .12s,box-shadow .12s; }
button:hover { filter:brightness(1.08); }
button:focus-visible { outline:3px solid var(--paper); outline-offset:3px; }
button:active { transform:translateY(2px); }
.add-button:hover { box-shadow:0 4px 0 #8fb641; }
.alarms-section { margin-top:28px; }
.list-heading { display:flex; justify-content:space-between; align-items:center; margin-bottom:12px; }
h2 { margin:0; font-size:18px; }
.count { margin:0; color:var(--lime); font-size:13px; font-weight:900; letter-spacing:.12em; }
.alarm-list { display:grid; gap:9px; margin:0; padding:0; list-style:none; }
.alarm-row { display:flex; align-items:center; gap:12px; min-width:0; padding:12px 13px; border:1px solid var(--line); border-radius:6px; background:#1d2a30; }
.alarm-time { color:var(--paper); font-size:24px; font-weight:800; font-variant-numeric:tabular-nums; letter-spacing:.02em; }
.alarm-info { flex:1; min-width:0; }
.alarm-label { overflow-wrap:anywhere; color:var(--muted); font-size:14px; }
.alarm-label:empty { display:none; }
.toggle { width:48px; height:28px; padding:3px; border:1px solid #607277; border-radius:20px; background:#33464c; cursor:pointer; flex:none; }
.toggle::before { content:""; display:block; width:20px; height:20px; border-radius:50%; background:var(--paper); transition:transform .15s; }
.toggle[aria-checked="true"] { border-color:var(--lime); background:#698a3c; }
.toggle[aria-checked="true"]::before { transform:translateX(19px); background:var(--lime); }
.delete-button { min-width:40px; min-height:40px; border:1px solid #76534e; border-radius:5px; background:transparent; color:var(--coral); font:inherit; font-size:20px; cursor:pointer; }
.delete-button:hover { background:#ff8b7218; }
.empty-state { margin:0; padding:20px 12px; border:1px dashed #53666a; border-radius:6px; color:var(--muted); text-align:center; }
footer { margin-top:26px; text-align:center; font-size:10px; }
footer span { color:var(--lime); }
@media (max-width:430px) { .alarm-form { grid-template-columns:1fr; padding:16px; } .label-field { grid-column:1; } .add-button { grid-column:1; } .alarm-row { gap:9px; padding:10px; } .alarm-time { font-size:21px; } }

const form = document.querySelector('#alarm-form');
const hourInput = document.querySelector('#hour');
const minuteInput = document.querySelector('#minute');
const labelInput = document.querySelector('#label');
const list = document.querySelector('#alarm-list');
const emptyState = document.querySelector('#empty-state');
const enabledCount = document.querySelector('#enabled-count');
const countWord = document.querySelector('#count-word');
let alarms = [];
let nextId = 1;

function render() {
  alarms.sort((a, b) => a.hour - b.hour || a.minute - b.minute || a.id - b.id);
  list.replaceChildren();
  for (const alarm of alarms) {
    const item = document.createElement('li');
    item.className = 'alarm-row';
    const time = document.createElement('time');
    time.className = 'alarm-time';
    time.dateTime = `${String(alarm.hour).padStart(2, '0')}:${String(alarm.minute).padStart(2, '0')}`;
    time.textContent = time.dateTime;
    const info = document.createElement('div');
    info.className = 'alarm-info';
    const label = document.createElement('div');
    label.className = 'alarm-label';
    label.textContent = alarm.label;
    info.append(time, label);
    const toggle = document.createElement('button');
    toggle.type = 'button';
    toggle.className = 'toggle';
    toggle.setAttribute('role', 'switch');
    toggle.setAttribute('aria-checked', String(alarm.enabled));
    toggle.setAttribute('aria-label', `Alarm ${time.textContent}${alarm.label ? `, ${alarm.label}` : ''}`);
    toggle.addEventListener('click', () => { alarm.enabled = !alarm.enabled; render(); });
    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'delete-button';
    remove.textContent = '×';
    remove.setAttribute('aria-label', `Delete alarm ${time.textContent}${alarm.label ? `, ${alarm.label}` : ''}`);
    remove.addEventListener('click', () => { alarms = alarms.filter(entry => entry.id !== alarm.id); render(); });
    item.append(info, toggle, remove);
    list.append(item);
  }
  const onCount = alarms.filter(alarm => alarm.enabled).length;
  enabledCount.textContent = String(onCount);
  countWord.textContent = onCount === 1 ? 'ALARM ON' : 'ALARMS ON';
  emptyState.hidden = alarms.length > 0;
  list.hidden = alarms.length === 0;
}

form.addEventListener('submit', event => {
  event.preventDefault();
  const hour = Number(hourInput.value);
  const minute = Number(minuteInput.value);
  if (!Number.isInteger(hour) || hour < 0 || hour > 23 || !Number.isInteger(minute) || minute < 0 || minute > 59) return;
  alarms.push({ id: nextId++, hour, minute, label: labelInput.value.trim(), enabled: true });
  form.reset();
  hourInput.focus();
  render();
});

render();
